style.css:
@-moz-document domain("bandlab.com") {
/* Background */
  body {
    background-color: #2b1d14 !important; /* dark brown */
    color: #f5e6d3 !important; /* light beige text */
  }

  /* Headers / Top Bar */
  header, .top-bar, .navbar, .header {
    background-color: #4a2f21 !important; /* medium-dark brown */
    color: #f5e6d3 !important;
  }

  /* Buttons */
  button, .btn, .primary-btn {
    background-color: #6b4226 !important; /* warm brown */
    border-color: #6b4226 !important;
    color: #fffaf3 !important;
  }
  button:hover, .btn:hover, .primary-btn:hover {
    background-color: #8c5a37 !important; /* lighter brown hover */
  }

  /* Panels & Cards */
  .card, .panel, .sidebar, .workspace, .content {
    background-color: #3a2619 !important; /* darker brown panels */
    border: 1px solid #6b4226 !important;
  }

  /* Links */
  a {
    color: #d4a373 !important; /* caramel */
  }
  a:hover {
    color: #e6c899 !important; /* lighter caramel */
  }
}
